steps.cmd:
cat > /opt/c2/nginx-c2.conf << 'CONF'
server {
    listen 443 ssl http2;
    server_name cdn.{companyName}.com;
    ssl_certificate /opt/certs/fullchain.pem;
    ssl_certificate_key /opt/certs/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    location /api/v2/telemetry { proxy_pass http://127.0.0.1:50050; }
    location / { return 200 '{"status":"ok"}'; add_header Content-Type application/json; }
}
CONF
nginx -t && nginx -s reload
